-- Owner-apply only. Do not run from CI or this repo's scripts.
-- Rolling Stone + Hyundai/Kia anti-theft filing_specs + filing_policies as DRAFTS.
-- After apply: a legal_reviewer must approve each spec and policy in
-- /admin/filing. Agent filing does not go live until those approvals.
-- ONE_CLICK_FILING_ENABLED must already be on for the public badge to show.
-- Generated by scripts/one-click-claim-profile-settlements.ts on 2026-11-25.

-- moss-krivin-v-penske-media-corporation
do $$
declare
  v_lawsuit uuid;
  v_spec_version integer;
  v_policy_version integer;
begin
  select id into v_lawsuit from public.lawsuits where slug = 'moss-krivin-v-penske-media-corporation';
  if v_lawsuit is null then
    raise notice 'skip moss-krivin-v-penske-media-corporation: no lawsuits row';
    return;
  end if;
  if exists (
    select 1 from public.filing_specs
    where lawsuit_id = v_lawsuit and status in ('draft', 'approved')
  ) then
    raise notice 'skip spec moss-krivin-v-penske-media-corporation: a live spec already exists';
  else
    select coalesce(max(version), 0) + 1 into v_spec_version
      from public.filing_specs where lawsuit_id = v_lawsuit;
    insert into public.filing_specs (lawsuit_id, version, content)
      values (v_lawsuit, v_spec_version, '{"official_form":{"url":"https://subscribe.rollingstone.com/krivin-rs","title":"Rolling Stone lifetime subscription claim form","challenges":[]},"class_definition":{"text":"People who bought a Rolling Stone lifetime print subscription from Penske Media Corporation. Moss Krivin v. Penske Media Corporation. Confirm the class on the official notice at subscribe.rollingstone.com/krivin-rs.","source_url":"https://subscribe.rollingstone.com/krivin-rs"},"attestation":{"text":"I declare under penalty of perjury that the information on this claim form is true and correct to the best of my knowledge.","source_url":"https://subscribe.rollingstone.com/krivin-rs"},"requires_agent_certification":false,"deadline":null,"member_fields":[{"field":"legal_name","official_label":"Full name","required":true},{"field":"first_name","official_label":"First name","required":true},{"field":"last_name","official_label":"Last name","required":true},{"field":"email","official_label":"Email address","required":true},{"field":"phone","official_label":"Phone number","required":false},{"field":"address.line1","official_label":"Street address","required":true},{"field":"address.line2","official_label":"Address line 2","required":false},{"field":"address.city","official_label":"City","required":true},{"field":"address.state","official_label":"State","required":true},{"field":"address.zip","official_label":"ZIP code","required":true}],"questions":[{"key":"class_member","official_label":"I bought a Rolling Stone lifetime print subscription as described on the official notice.","help":null,"type":"yes_no","required":true,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false},{"key":"subscription_email","official_label":"Email address on the Rolling Stone subscription, if different from the email on this form","help":null,"type":"email","required":false,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false},{"key":"notice_id","official_label":"Notice ID (if listed on your notice)","help":null,"type":"notice_id","required":false,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false}],"benefit_tiers":[],"payout_options":[{"value":"check","official_label":"Check"},{"value":"other","official_label":"Other payment method listed on the official form"}],"form_field_order":["member.first_name","member.last_name","member.legal_name","member.email","member.phone","member.address.line1","member.address.line2","member.address.city","member.address.state","member.address.zip","answers.class_member","answers.subscription_email","answers.notice_id","payout_method"],"jev_rules":[],"desk_notes":"Official path is subscribe.rollingstone.com/krivin-rs. Fill name, address, email and the subscription email from the packet. Stop if a login, captcha or payment-account field appears. Never collect PayPal/Venmo account details. Never submit a test identity. Policy stays draft until a legal_reviewer approves after the dry-run."}'::jsonb);
    raise notice 'inserted spec draft moss-krivin-v-penske-media-corporation v%', v_spec_version;
  end if;
  if exists (
    select 1 from public.filing_policies
    where lawsuit_id = v_lawsuit and status in ('draft', 'approved')
  ) then
    raise notice 'skip policy moss-krivin-v-penske-media-corporation: a live policy already exists';
  else
    select coalesce(max(version), 0) + 1 into v_policy_version
      from public.filing_policies where lawsuit_id = v_lawsuit;
    insert into public.filing_policies (
      lawsuit_id, version, agent_filing, channels, allowed_states, sources_reviewed, notes
    ) values (
      v_lawsuit,
      v_policy_version,
      'allowed',
      '[{"type":"filing_desk","enabled":true,"daily_capacity":10,"sla_business_days":2,"min_days_before_deadline":5,"accepts_documents":false,"instructions":"Fill the official form at https://subscribe.rollingstone.com/krivin-rs from the packet. Never submit a test identity. Stop if a captcha, login, or proof upload appears."}]'::jsonb,
      '["AL","AK","AZ","AR","CA","CO","CT","DE","DC","FL","GA","HI","ID","IL","IN","IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VT","VA","WA","WV","WI","WY"]'::jsonb,
      '[{"kind":"claim_form","title":"Rolling Stone lifetime subscription official claims site","url":"https://subscribe.rollingstone.com/krivin-rs","document_ref":null,"reviewed_on":"2026-11-25","notes":null}]'::jsonb,
      'Draft one-click policy for moss-krivin-v-penske-media-corporation. Owner must approve in admin after applying SQL. Administrator: Penske Media / Rolling Stone.'
    );
    raise notice 'inserted policy draft moss-krivin-v-penske-media-corporation v%', v_policy_version;
  end if;
end $$;

