      from public.filing_specs where lawsuit_id = v_lawsuit;
    insert into public.filing_specs (lawsuit_id, version, content)
      values (v_lawsuit, v_spec_version, '{"official_form":{"url":"https://www.hkmultistateimmobilizersettlement.com/submit-claim","title":"Hyundai and Kia anti-theft / immobilizer claim form","challenges":[]},"class_definition":{"text":"People who own or lease an eligible Hyundai or Kia that was not factory-equipped with an immobilizer. Cash claims also need a qualifying theft or theft attempt on or after April 29, 2025 while the software upgrade was installed or scheduled, and before the zinc sleeve or March 31, 2027. Confirm the class and model-year list on the official notice.","source_url":"https://www.hkmultistateimmobilizersettlement.com/"},"attestation":{"text":"I declare under penalty of perjury that the information on this claim form is true and correct to the best of my knowledge.","source_url":"https://www.hkmultistateimmobilizersettlement.com/"},"requires_agent_certification":false,"deadline":{"date":"2027-03-31","time_zone":"America/New_York","type":"submit_online_by"},"member_fields":[{"field":"legal_name","official_label":"Full name","required":true},{"field":"first_name","official_label":"First name","required":true},{"field":"last_name","official_label":"Last name","required":true},{"field":"email","official_label":"Email address","required":true},{"field":"phone","official_label":"Phone number","required":false},{"field":"address.line1","official_label":"Street address","required":true},{"field":"address.line2","official_label":"Address line 2","required":false},{"field":"address.city","official_label":"City","required":true},{"field":"address.state","official_label":"State","required":true},{"field":"address.zip","official_label":"ZIP code","required":true}],"questions":[{"key":"class_member","official_label":"I own or lease an eligible Hyundai or Kia that was not factory-equipped with an immobilizer, as described on the official notice.","help":null,"type":"yes_no","required":true,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false},{"key":"vin","official_label":"Vehicle identification number (VIN)","help":null,"type":"vin","required":true,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false},{"key":"notice_id","official_label":"Notice ID (if listed on your notice)","help":null,"type":"notice_id","required":false,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false}],"benefit_tiers":[{"key":"theft_cash","official_label":"Cash for a qualifying theft or theft attempt","description":"Records that show the software upgrade was installed or an appointment was scheduled, plus the qualifying theft or theft attempt. Check the official notice for what counts.","proof":[{"kind":"theft_docs","official_label":"Records of the qualifying theft or theft attempt and of the software upgrade or scheduled appointment","help":null,"required":true,"min_files":1,"max_files":8,"accepted_mime":["image/jpeg","image/png","image/heic","image/heif","image/webp","application/pdf"],"health_flag":false}]}],"payout_options":[{"value":"check","official_label":"Check"},{"value":"other","official_label":"Other payment method listed on the official form"}],"form_field_order":["member.first_name","member.last_name","member.legal_name","member.email","member.phone","member.address.line1","member.address.line2","member.address.city","member.address.state","member.address.zip","answers.class_member","answers.vin","answers.notice_id","benefit_tier","documents.theft_docs","payout_method"],"jev_rules":[],"desk_notes":"Official submit-claim at hkmultistateimmobilizersettlement.com. VIN path plus theft-document upload when a no-notice identity form exists. Fill VIN and contact from the packet. Upload only files the member attached. Stop if a captcha, login, or identity check appears. Never submit a test identity. 2026-11-25 dry-run: submit-claim showed a notice login; not fillable from profile. Do not approve until a no-notice VIN path exists."}'::jsonb);
    raise notice 'inserted spec draft hyundai-kia-vehicle-theft v%', v_spec_version;
  end if;
  if exists (
    select 1 from public.filing_policies
    where lawsuit_id = v_lawsuit and status in ('draft', 'approved')
  ) then
    raise notice 'skip policy hyundai-kia-vehicle-theft: a live policy already exists';
  else
    select coalesce(max(version), 0) + 1 into v_policy_version
      from public.filing_policies where lawsuit_id = v_lawsuit;
    insert into public.filing_policies (
      lawsuit_id, version, agent_filing, channels, allowed_states, sources_reviewed, notes
    ) values (
      v_lawsuit,
      v_policy_version,
      'allowed',
      '[{"type":"filing_desk","enabled":true,"daily_capacity":10,"sla_business_days":2,"min_days_before_deadline":5,"accepts_documents":true,"instructions":"Fill the official form at https://www.hkmultistateimmobilizersettlement.com/submit-claim from the packet. Use the VIN path. Upload only the member’s theft documents. Never submit a test identity. Stop if a captcha, login, or identity check appears."}]'::jsonb,
      '["AL","AK","AZ","AR","CA","CO","CT","DE","DC","FL","GA","HI","ID","IL","IN","IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VT","VA","WA","WV","WI","WY"]'::jsonb,
      '[{"kind":"claim_form","title":"Hyundai and Kia anti-theft / immobilizer official claims site","url":"https://www.hkmultistateimmobilizersettlement.com/","document_ref":null,"reviewed_on":"2026-11-25","notes":null}]'::jsonb,
